public boolean splitArraySameAverage(int[] nums) {
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }
    if (sum % 2 != 0) {
        return false;
    }
    int target = sum / 2;
    int[] first = new int[nums.length / 2];
    int[] second = new int[nums.length - first.length];
    int i = 0, j = 0;
    for (int num : nums) {
        if (i < first.length) {
            first[i++] = num;
        } else {
            second[j++] = num;
        }
    }
    int leftSum = 0, rightSum = 0;
    for (int num : first) {
        leftSum += num;
    }
    for (int num : second) {
        rightSum += num;
    }
    for (int i = 0; i < first.length; i++) {
        if (leftSum == target && rightSum == target) {
            return true;
        }
        leftSum -= first[i];
        rightSum += first[i];
    }
    return false;
}
