import java.util.List;
import java.util.Collections;
import java.util.stream.Collectors;

public class SquarePermutations {

    public static int squarePermutations(int[] A) {
        List<List<Integer>> permutations = new ArrayList<>();
        // Transform the input array into a list of indices
        List<Integer>indices = IntStream.range(0, A.length).boxed().collect(Collectors.toList());
        // Generate all permutations of the indices
        permute(indices, new boolean[A.length], new LinkedList<>(), permutations);
        // Return the count of square permutations
        return permutations.stream().filter(permutation -> isSquarePermutation(permutation.toArray(new int[0]))).count();
    }

    private static void permute(List<Integer> array, boolean[] used, List<Integer> temp, List<List<Integer>> permutations) {
        if (temp.size() == array.size()) {
            permutations.add(new ArrayList<>(temp));
            return;
        }
        for (int i = 0; i < array.size(); i++) {
            if (used[i] || (i > 0 && array.get(i) == array.get(i - 1) && !used[i - 1])) {
                continue;
            }
            used[i] = true;
            temp.add(array.get(i));
            permute(array, used, temp, permutations);
            temp.remove(temp.size() - 1);
            used[i] = false;
        }
    }

    private static boolean isSquarePermutation(int[] permutation) {
        for (int i = 1; i < permutation.length; i++) {
            if (!isSumSquare(permutation[i - 1], permutation[i])) {
                return false;
            }
        }
        return true;
    }

    private static boolean isSumSquare(int a, int b) {
        return Math.pow(Math.sqrt(a) + Math.sqrt(b), 2) == a + b;
    }
}
