public static List<String> centerSymmetricNumbers(int n) {
    List<String> centerSymmetricNumbers = new ArrayList<>();
    for (int i = 0; i <= n / 2; i++) {
        StringBuilder leftHalf = new StringBuilder();
        StringBuilder rightHalf = new StringBuilder();

        // Generate left half of the center symmetric number
        for (int j = 0; j <= i; j++) {
            leftHalf.append(j);
        }

        // If left half is a single digit, right half is also a single digit
        if (leftHalf.length() == 1) {
            for (int j = i; j <= n / 2; j++) {
                rightHalf.append(n - j);
            }
        } else {
            // Generate right half of the center symmetric number
            for (int j = 0; j <= i; j++) {
                rightHalf.append(n - j);
            }
        }

        // Combine left and right half and reverse them to get a center symmetric number
        String centerSymmetricNumber = leftHalf.toString() + rightHalf.reverse().toString();
        centerSymmetricNumbers.add(centerSymmetricNumber);
    }
    return centerSymmetricNumbers;
}
