public static boolean isBoomerang(int[][] points) {
    int numPoints = points.length;
    if (numPoints != 3) {
        throw new IllegalArgumentException("Expected 3 points, got " + numPoints);
    }

    // Calculate vectors between consecutive points
    double x12 = points[1][0] - points[0][0];
    double y12 = points[1][1] - points[0][1];
    double x23 = points[2][0] - points[1][0];
    double y23 = points[2][1] - points[1][1];

    // Calculate the cross product of the vectors
    double crossProduct = x12 * y23 - y12 * x23;

    // A boomerang is formed if the cross product is non-zero
    return crossProduct != 0;
}
